class ImageGenToolCall(BaseAPIType):
    """An image generation request made by the model.

    Attributes:
        type: The type of the image generation call. Always
            `image_generation_call`.
        id: The unique ID of the image generation call.
        status: The status of the image generation call.
        error: Details of a moderation failure, when available.
    """

    __upstream_schema__ = "ImageGenToolCall"
    model_config = ConfigDict(extra="forbid")
    type: Annotated[
        Literal["image_generation_call"],
        Field(
            description=(
                "The type of the image generation call. Always "
                "`image_generation_call`."
            )
        ),
    ] = "image_generation_call"
    id: Annotated[
        str, Field(description="The unique ID of the image generation call.")
    ]
    status: Annotated[
        Literal["in_progress", "completed", "generating", "failed"],
        Field(description="The status of the image generation call."),
    ]
    result: str | None
    error: Annotated[
        ImageGenToolCallError | MISSING,
        Field(
            description=("Details of a moderation failure, when available.")
        ),
    ] = MISSING
    size: (
        str | Literal["1024x1024", "1024x1536", "1536x1024"] | None | MISSING
    ) = MISSING
    quality: (
        Literal["low", "medium", "high", "xhigh", "max", "auto"]
        | None
        | MISSING
    ) = MISSING
    action: ImageGenActionEnum | None | MISSING = MISSING
    background: ImageBackground | None | MISSING = MISSING
    output_format: ImageOutputFormat | None | MISSING = MISSING
    svg_usage: SvgUsage | MISSING = MISSING
    revised_prompt: str | None | MISSING = MISSING


class MCPToolCall(BaseAPIType):
    """An invocation of a tool on an MCP server.

    Attributes:
        type: The type of the item. Always `mcp_call`.
        id: The unique ID of the tool call.
        server_label: The label of the MCP server running the tool.
        name: The name of the tool that was run.
        arguments: A JSON string of the arguments passed to the tool.
        error: The error from the tool call, if any.
        status: The status of the tool call. One of `in_progress`,
            `completed`, `incomplete`, `calling`, or `failed`.
    """

    __upstream_schema__ = "MCPToolCall"
    model_config = ConfigDict(extra="forbid")
    type: Annotated[
        Literal["mcp_call"],
        Field(description="The type of the item. Always `mcp_call`."),
    ] = "mcp_call"
    id: Annotated[str, Field(description="The unique ID of the tool call.")]
    server_label: Annotated[
        str, Field(description="The label of the MCP server running the tool.")
    ]
    name: Annotated[
        str, Field(description="The name of the tool that was run.")
    ]
    arguments: Annotated[
        str,
        Field(
            description=("A JSON string of the arguments passed to the tool.")
        ),
    ]
    output: str | None | MISSING = MISSING
    error: Annotated[
        MCPToolCallError | None | MISSING,
        Field(description="The error from the tool call, if any."),
    ] = MISSING
    status: Annotated[
        MCPToolCallStatus | MISSING,
        Field(
            description=(
                "The status of the tool call. One of "
                "`in_progress`, `completed`, `incomplete`, "
                "`calling`, or `failed`."
            )
        ),
    ] = MISSING
    approval_request_id: str | None | MISSING = MISSING


class CustomToolCallOutput(BaseAPIType):
    """`CustomToolCallOutput` from the OpenAI API.

    The output of a custom tool call from your code, being sent back
    to the
    model.

    Attributes:
        type: The type of the custom tool call output. Always
            `custom_tool_call_output`.
        id: The unique ID of the custom tool call output in the
            OpenAI platform.
        call_id: The call ID, used to map this custom tool call
            output to a custom tool call.
        caller: The execution context that produced this tool call.
        output: The output from the custom tool call generated by
            your code. Can be a string or an list of output content.
    """

    __upstream_schema__ = "CustomToolCallOutput"
    model_config = ConfigDict(extra="forbid")
    type: Annotated[
        Literal["custom_tool_call_output"],
        Field(
            description=(
                "The type of the custom tool call output. "
                "Always `custom_tool_call_output`."
            )
        ),
    ] = "custom_tool_call_output"
    id: Annotated[
        str | MISSING,
        Field(
            description=(
                "The unique ID of the custom tool call output "
                "in the OpenAI platform."
            )
        ),
    ] = MISSING
    call_id: Annotated[
        str,
        Field(
            description=(
                "The call ID, used to map this custom tool call"
                " output to a custom tool call."
            )
        ),
    ]
    caller: ToolCallCallerParam | None | MISSING = MISSING
    output: Annotated[
        str | list[FunctionAndCustomToolCallOutput],
        Field(
            description=(
                "The output from the custom tool call generated"
                " by your code.\nCan be a string or an list of "
                "output content."
            )
        ),
    ]


